def min_intervals_to_cover(intervals, L):
    # Check if L is covered by any interval
    for interval in intervals:
        if interval[0] <= L <= interval[1]:
            return len(intervals)

    # Find the smallest interval that covers L
    smallest_interval = min(intervals, key=lambda x: x[1] - x[0])
    if smallest_interval[1] <= L:
        return len(intervals)

    # Find the smallest interval that covers L and the smallest interval that covers the smallest interval
    smallest_covering_intervals = [smallest_interval]
    smallest_covering_intervals.extend(combination(intervals, 2) if L - smallest_interval[1] > smallest_interval[0] else [])

    # Find the smallest number of intervals needed to cover L and the smallest intervals
    return len(smallest_covering_intervals) + min(len(combination(smallest_covering_intervals, 2)), len(smallest_covering_intervals) - 1)

