def coin_change_ways(coins: list[int], amount: int) -> int:
    n = len(coins)
    if amount == 0:
        return 1

    # Base case: no coins available
    if amount < 0 or n == 0:
        return 0

    # Create a table to store the number of ways to get the remaining amount after removing one coin
    table = [0] * (abs(amount) + 1)
    table[0] = 1

    for i in range(1, n + 1):
        for j in range(abs(amount), 0, -1):
            if coins[i - 1] <= j:
                table[j] += table[j - coins[i - 1]]

    return table[amount]

def coin_change_ways(coins: list[int], amount: int) -> int:
    if amount < 0:
        return 0

    if amount == 0:
        return 1

    result = []
