    table = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the table in a bottom-up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                table[i][j] = j
            elif j == 0:
                table[i][j] = i
            else:
                if a[i - 1] == b[j - 1]:
                    table[i][j] = table[i - 1][j - 1]
                else:
                    table[i][j] = min(table[i - 1][j], table[i][j - 1], table[i - 1][j - 1]) + 1

    return table[m][n]

