def lru_simulate(capacity: int, ops: list[list]):
    cache = collections.defaultdict(dict)

    for op in ops:
        key, *args = op
        if len(args) != 2:
            raise ValueError("Expected 2 arguments for ops, got {}".format(len(args)))

        if args[0] in ('put', 'update'):
            value = args[1]
            if args[0] == 'put':
                cache[key][0] = value
            else:
                cache[key][1] = value
        elif args[0] == 'get':
            if key in cache:
                value = cache[key][0] if cache[key] else -1
                cache[key] = (value, None)
            else:
                value = -1
                cache[key] = (value, None)
            return value

        else:
            raise ValueError("Invalid operation: {}".format(args[0]))

    results = []
    for op in ops:
        key, *args = op
        if args[0] == 'put':
            value = cache[key][0] if cache[key] else -1
            cache[key] = (args[1], None)
        elif args[0] == 'get':
            value = -1
            cache[key] = (value, None)
            results.append(value)
        else:
            raise ValueError("Invalid operation: {}".format(args[0]))

    return results
